Below are the few store procedures which ran during the given time period


CREATE FUNCTION [Tenant].[CalculateHouseholdCount](@householdId INT, @isCA BIT)  RETURNS INT  AS  BEGIN   DECLARE @result int;   -- CA   IF @isCA = 1    SET @result = (SELECT COUNT(PROF.HouseholdMemberProfileId) [HouseholdSize] FROM Tenant.HouseholdComposition HC    JOIN Tenant.HouseholdMemberProfile PROF ON PROF.HouseholdMemberProfileId = HC.HouseholdMemberProfileId    WHERE HC.IsActive = 1 AND HC.HouseholdId = @householdId AND PROF.IsEligibleForCA = 1 GROUP BY HC.HouseholdId)   -- NCA   ELSE    SET @result = (SELECT COUNT(PROF.HouseholdMemberProfileId) [HouseholdSize] FROM Tenant.HouseholdComposition HC    JOIN Tenant.HouseholdMemberProfile PROF ON PROF.HouseholdMemberProfileId = HC.HouseholdMemberProfileId    WHERE HC.IsActive = 1 AND HC.HouseholdId = @householdId AND    (PROF.IsEligibleForCA = 0 OR PROF.IsEligibleForCA IS NULL) GROUP BY HC.HouseholdId)     RETURN CASE WHEN @result IS NULL THEN 0 ELSE @result END  END   

CREATE FUNCTION [Tenant].[CalculateHouseholdCount](@householdId INT, @isCA BIT)  RETURNS INT  AS  BEGIN   DECLARE @result int;   -- CA   IF @isCA = 1    SET @result = (SELECT COUNT(PROF.HouseholdMemberProfileId) [HouseholdSize] FROM Tenant.HouseholdComposition HC    JOIN Tenant.HouseholdMemberProfile PROF ON PROF.HouseholdMemberProfileId = HC.HouseholdMemberProfileId    WHERE HC.IsActive = 1 AND HC.HouseholdId = @householdId AND PROF.IsEligibleForCA = 1 GROUP BY HC.HouseholdId)   -- NCA   ELSE    SET @result = (SELECT COUNT(PROF.HouseholdMemberProfileId) [HouseholdSize] FROM Tenant.HouseholdComposition HC    JOIN Tenant.HouseholdMemberProfile PROF ON PROF.HouseholdMemberProfileId = HC.HouseholdMemberProfileId    WHERE HC.IsActive = 1 AND HC.HouseholdId = @householdId AND    (PROF.IsEligibleForCA = 0 OR PROF.IsEligibleForCA IS NULL) GROUP BY HC.HouseholdId)     RETURN CASE WHEN @result IS NULL THEN 0 ELSE @result END  END   

CREATE PROC [dbo].[usp_GetUserSubsidies]         @UserId int         AS         /***************************************************************************************************        Filename:          .[dbo].[usp_GetUserSubsidies]         Create Date:        2020-09-11        Author:             Tushar Malakar        Version:   1.0        Description:  List of Subsidy         ****************************************************************************************************        SUMMARY OF CHANGES        Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments        --------------------------------------------------------------------------------------------------          1.0     2020-09-11      Tushar Malakar          LME-5129             N/A             2.0     2022-06-02      Ganesh Motamarri        LME-13588            Group by is not required in this scenario, Landlord.user also removed      3.0     2023-06-01      Vishnu Raj              LME-13588            Added NoLock            ***************************************************************************************************/         BEGIN         IF @UserId > 0          BEGIN           SELECT DISTINCT CP.[Name], CP.[ProgramId], CP.[IsActive], CP.[Description] FROM            Landlord.Assignment LA  WITH(NOLOCK)       JOIN Landlord.AssignmentChange LAC WITH(NOLOCK) ON LAC.AssignmentChangeId = LA.AssignmentChangeId                   LEFT JOIN Landlord.Property LP WITH(NOLOCK) ON LP.PropertyId = LA.PropertyId           JOIN Landlord.Unit LU WITH(NOLOCK) ON LU.PropertyId = LP.PropertyId OR LA.UnitId = LU.UnitId                   JOIN Tenant.TenantUnit TU WITH(NOLOCK) ON TU.UnitId = LU.UnitId           JOIN Landlord.Leasing LL WITH(NOLOCK) on LL.UnitId = TU.UnitId           JOIN Tenant.Application TA WITH(NOLOCK) ON TA.ApplicationId = LL.ApplicationId           JOIN Config.Program CP WITH(NOLOCK) ON CP.ProgramId = TA.ProgramId           WHERE            LA.IsActive = 1 and           LA.UserId = @UserId  and -- Comment this line to see programs for all owners           LA.UserTypeId = 1 and -- Owner           LAC.AssignmentChangeStatusId = 2 and -- Approved Owner           TA.ApplicationStatusId = 9 and -- Approved Application (this should be unnecessary from next line)           TU.IsActive = 1          --GROUP BY CP.[Name], CP.[ProgramId], CP.[IsActive], CP.[Description]          END         END



CREATE PROC [dbo].[usp_GetUnitTimeline] @unitId INT  AS    /***************************************************************************************************    Filename:          [usp_GetUnitTimeline]    Create Date:        2020-09-08    Author:             Mike Bajor, Fred Erlikh    Version:            2.0    Description:          ****************************************************************************************************    SUMMARY OF CHANGES    Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments    ------------------- ------------------- ------------------------------------------------------------      1.0     2020-09-09        Mike Bajor        n/a        end payments: use PaymentDetail instead of PaymentDetail_History      1.1    2020-09-10    Fred Erlikh        n/a        end payments: use PaymentDetail_History instead of PaymentDetail + use inner join      1.2    2020-09-18    Fred Erlikh        n/a        move withdraw/deny into one query + change statuses to (10, 11)      1.3    2020-09-18    Fred Erlikh        n/a        end payments: use PaymentDetail + PaymentDetail_History instead      1.4    2020-09-18    Mike Bajor        n/a        refactor: application is active + Unsuccessful Move Out Confirmed      1.5    2020-09-18    Fred Erlikh        n/a        refactor: end payments to use left joins on history      1.6    2020-09-21    Fred Erlikh        n/a        fix: Application Withdrawn/Denied if + only if it was never approved      1.7    2020-12-17      Mike Bajor        n/a        fix: lease created now checks lease history as well / withdraw logic checks leasing history      1.8    2020-12-18      Mike Bajor        n/a        fix: new assigment logic now checks for approved payment Change for new payee      1.9    2021-02-12    Diana Stadniychuk    LME-4401    added event: Unit Status Changed Manually      2.0    2021-02-12    Travis Simon      LME-10013    update: Change 'New Assignment' Joins from Inner to Left to include Assignments without a Payment Change or Payee Payment Mode      2.1    2021-10-05    Vance Rivera      LME-13662    Update: removed commented scripts. Update to prepopulate temp table with paymentDetail_History for unit. Update to offset validFrom date by 10 seconds.      2.2    2021-10-07    Pavan Muddana  LME-13686    Update: Added LegalName column to resultset for unit history.    ***************************************************************************************************/    BEGIN     SET NOCOUNT ON        -- Unit Status Changes --        DECLARE @unitStatusId int,                @prevStatusId int,                @validFrom    datetime2,                @validTo      datetime2;        DECLARE @statusChanges table          (             [UnitStatusId] int,             [PrevStatusId] int,             [ValidFrom]    datetime2,             [ValidTo]      datetime2,             [EventType]    varchar(128),             [SubEventType] varchar(128)          );        DECLARE status_cursor CURSOR FOR          (SELECT *           FROM   Landlord.GetUnitStatusChanges (@unitId))            --Populate PaymentDetail_History_Temp for UnitId          IF Object_id('tempdb..#PaymentDetail_History_Temp') IS NOT NULL              DROP TABLE #PaymentDetail_History_Temp            SELECT *          INTO #PaymentDetail_History_Temp          FROM Payment.PaymentDetail_History PDH          WHERE PDH.PaymentDetailId IN (              SELECT PD.PaymentDetailId              FROM Payment.PaymentDetail PD              JOIN Payment.PaymentInstruction PPI              ON PPI.PaymentInstructionId = PD.PaymentInstructionId              JOIN Tenant.Application TA              ON TA.ApplicationId = PPI.ApplicationId              JOIN Landlord.Leasing LL              ON LL.ApplicationId = PPI.ApplicationId              WHERE LL.UnitId = @unitId)          OPEN status_cursor          FETCH NEXT FROM status_cursor INTO @unitStatusId, @prevStatusId,        @validFrom,        @validTo          WHILE @@FETCH_STATUS = 0          BEGIN                            set @validFrom = DateAdd(SS,-10, @validFrom) -- need to offset the date in the case where validfrom and validTo are the same datetime values              PRINT (@validFrom)              PRINT (@validTo)              PRINT (@unitStatusId)                IF( @unitStatusId = 1 ) -- Occupied                BEGIN                      -- Application is Active                    INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId        [UnitStatusId],                                    @prevStatusId        [PrevStatusId],                                    @validFrom           [ValidFrom],                                    @validTo             [ValidTo],                                    'Application Active' [SubEventType]                    FROM   (SELECT A.*                            FROM   Tenant.Application A WITH(NoLock)                                   JOIN Landlord.Leasing L WITH(NoLock)                                     ON L.ApplicationId = A.ApplicationId                            WHERE  A.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId                            UNION                            SELECT AH.*                            FROM   Tenant.Application_History AH WITH(NoLock)                                   JOIN Landlord.Leasing L WITH(NoLock)                                     ON L.ApplicationId = AH.ApplicationId                            WHERE  AH.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId) A                    WHERE  A.ApplicationStatusId in ( 9 )                  END              ELSE IF( @unitStatusId = 2 ) -- Reserved                BEGIN                      -- Lease is created                    INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId   [UnitStatusId],                                    @prevStatusId   [PrevStatusId],                                    @validFrom      [ValidFrom],                                    @validTo        [ValidTo],                                    'Lease Created' [SubEventType]                    FROM   (SELECT L.*                            FROM   (SELECT *                                    FROM   Landlord.Leasing L WITH(NoLock)                                    UNION                                    SELECT *                                    FROM   Landlord.Leasing_History LH WITH(NoLock                                           ))                                   L                                   JOIN Tenant.Application_History AH WITH(NoLock)                                     ON AH.ApplicationId = L.ApplicationId                                   JOIN Landlord.Unit_History UH WITH(NoLock)                                     ON UH.UnitId = @unitId                            WHERE  UH.SysStartTime BETWEEN @validFrom AND @validTo                                   AND AH.ApplicationStatusId in ( 2, 3, 4, 5,                                                                   6, 7, 8 )                                   AND L.UnitId = @unitId) L                                        -- Unsuccessful Move Out Confirmed                    INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId           [UnitStatusId],                                    @prevStatusId           [PrevStatusId],                                    @validFrom              [ValidFrom],                                    @validTo                [ValidTo],                                    'Unsuccessful Move Out' [SubEventType]                    FROM   (SELECT A.*                            FROM   Tenant.Application A WITH(NoLock)                                   INNER JOIN Landlord.Leasing L WITH(NoLock)                                           ON L.ApplicationId = A.ApplicationId                                   INNER JOIN Landlord.Unit_History UH WITH(NoLock                                              )                                           ON UH.UnitId = L.UnitId                            WHERE  A.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId                            UNION                            SELECT AH.*                            FROM   Tenant.Application_History AH WITH(NoLock)                                   INNER JOIN Landlord.Leasing L WITH(NoLock)                                           ON L.ApplicationId = AH.ApplicationId                                   INNER JOIN Landlord.Unit_History UH WITH(NoLock                                              )                                           ON UH.UnitId = L.UnitId                            WHERE  AH.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId) A                    WHERE  A.ApplicationStatusId = 10                           AND A.IsMoveOut = 0                                        INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId,                                    @prevStatusId   [PrevStatusId],                                    @validFrom      [ValidFrom],                                    @validTo        [ValidTo],                                    'Payment Ended' [SubEventType]                    FROM   Landlord.Leasing L WITH(NoLock)                           INNER JOIN Payment.PaymentInstruction PI WITH(NoLock)                                   ON PI.ApplicationId = L.ApplicationId                           INNER JOIN Payment.PaymentDetail PD WITH(NoLock)                                   ON PD.PaymentInstructionId = PI.PaymentInstructionId                           LEFT JOIN #PaymentDetail_History_Temp PDH WITH(NoLock)                                  ON PDH.PaymentInstructionId =                                     PI.PaymentInstructionId                    WHERE  ( ( PDH.SysStartTime BETWEEN @validFrom AND @validTo                               AND PDH.PaymentStatusId = 2 )                              OR ( PD.SysStartTime BETWEEN @validFrom AND @validTo                                   AND PD.PaymentStatusId = 2 ) )                           AND L.UnitId = @unitId                       END              ELSE IF( @unitStatusId = 3 ) -- Unknown                BEGIN                                        -- Unsuccessful Move Out Confirmed                    INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId           [UnitStatusId],                                    @prevStatusId           [PrevStatusId],                                    @validFrom              [ValidFrom],                                    @validTo                [ValidTo],                                    'Unsuccessful Move Out' [SubEventType]                    FROM   (SELECT A.*                            FROM   Tenant.Application A WITH(NoLock)                                   INNER JOIN Landlord.Leasing L WITH(NoLock)                                           ON L.ApplicationId = A.ApplicationId                                   INNER JOIN Landlord.Unit_History UH WITH(NoLock                                              )                                           ON UH.UnitId = L.UnitId                            WHERE  A.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId                            UNION                            SELECT AH.*                            FROM   Tenant.Application_History AH WITH(NoLock)                                   INNER JOIN Landlord.Leasing L WITH(NoLock)                                           ON L.ApplicationId = AH.ApplicationId                                   INNER JOIN Landlord.Unit_History UH WITH(NoLock                                              )                                           ON UH.UnitId = L.UnitId                            WHERE  AH.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId) A                    WHERE  A.ApplicationStatusId = 10                           AND A.IsMoveOut = 0                                        -- Application is Withdrawn/Denied                    INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId,                                    @prevStatusId                  [PrevStatusId],                                    @validFrom                     [ValidFrom],                                    @validTo                       [ValidTo],                                    'Application Withdrawn/Denied' [SubEventType]                    FROM   (SELECT A.*                            FROM   (SELECT A.*                                    FROM   Tenant.Application A WITH(NoLock)                                    UNION                                    SELECT AH.*                                    FROM   Tenant.Application_History AH WITH(                                           NoLock                                           )) A                                   JOIN Landlord.Leasing_History L WITH(NoLock)                                     ON L.ApplicationId = A.ApplicationId                            WHERE  L.SysStartTime BETWEEN @validFrom AND @validTo                                   AND L.UnitId = @unitId                                   AND NOT EXISTS                                       (SELECT *                                        FROM   Tenant.Application_History                                               AH                                               WITH(                                               NoLock)                                        WHERE  AH.ApplicationId =                                               A.ApplicationId                                               AND AH.ApplicationStatusId                                                   = 9                                       )                           ) A                    WHERE  A.ApplicationStatusId in ( 10, 11 )                                         -- End Payment Approved                                      INSERT INTO @statusChanges                                ([UnitStatusId],                                 [PrevStatusId],                                 [ValidFrom],                                 [ValidTo],                                 [SubEventType])                    SELECT DISTINCT @unitStatusId,                                    @prevStatusId   [PrevStatusId],                                    @validFrom      [ValidFrom],                                    @validTo        [ValidTo],                                    'Payment Ended' [SubEventType]                    FROM   Landlord.Leasing L WITH(NoLock)                           INNER JOIN Payment.PaymentInstruction PI WITH(NoLock)                                   ON PI.ApplicationId = L.ApplicationId                           INNER JOIN Payment.PaymentDetail PD WITH(NoLock)                                   ON PD.PaymentInstructionId = PI.PaymentInstructionId                           LEFT JOIN #PaymentDetail_History_Temp PDH WITH(NoLock)                                  ON PDH.PaymentInstructionId =                                     PI.PaymentInstructionId                    WHERE  ( ( PDH.SysStartTime BETWEEN @validFrom AND @validTo                               AND PDH.PaymentStatusId = 2 )                              OR ( PD.SysStartTime BETWEEN @validFrom AND @validTo                                   AND PD.PaymentStatusId = 2 ) )                           AND L.UnitId = @unitId                                 END                FETCH NEXT FROM status_cursor INTO @unitStatusId, @prevStatusId,              @validFrom,              @validTo          END          --SELECT * FROM @statusChanges        CLOSE status_cursor;          DEALLOCATE status_cursor;          -- Unit Status Changes --        Select T.*        FROM   (SELECT DISTINCT 'Record Created' [EventType],                                'Record Created' [FilterKeyword],                                ''               [SubEventType],                                UH.CreatedDate   [Date],                                NULL             [FirstName],                                NULL             [LastName],                                NULL             [UserId],                                NULL             [ContactFirstName],                                NULL             [ContactLastName],                                NULL             [LegalName],                                NULL             [IsBusiness],                                UH.UnitStatusId  [UnitStatusId]                FROM   Landlord.Unit_History UH WITH(NoLock)                WHERE  UH.UnitId = @unitId                       AND UH.CreatedDate IS NOT NULL                       AND UH.UpdatedDate IS NULL                -- this check to be deleted. temp to fix bad data (Mike [08/28/20])                UNION ALL                -- Unit Status Changed Manually                SELECT DISTINCT 'Unit Status'               [EventType],                                'Status'                    [FilterKeyword],                                'Manual Unit Status Change' [SubEventType],                                L.CreatedDate               [Date],                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                L.UnitStatusId                FROM   Landlord.UnitStatusChange L WITH(NoLock)                WHERE  L.UnitId = @unitId                UNION ALL                SELECT DISTINCT 'New Assignment' [EventType],                                'Payee'          [FilterKeyword],                                '',                                A.CreatedDate    [Date],                                LL.FirstName,                                LL.LastName,                                LL.UserId,                                LL.ContactFirstName,                                LL.ContactLastName,                                LL.LegalName,                                LL.IsBusiness,                                NULL                FROM   Landlord.Assignment A WITH(NoLock)                       INNER JOIN Landlord.[User] LL WITH(NoLock)                               ON A.UserId = LL.UserId                       LEFT JOIN Landlord.PayeePaymentMode PPM WITH(NoLock)                              ON PPM.AssignmentId = A.AssignmentId                       LEFT JOIN Landlord.PaymentChange PC WITH(NoLock)                              ON PC.PaymentChangeId = PPM.PaymentChangeId                WHERE  LL.IsActive = 1                       AND A.UserTypeId = 2 --payee                       AND A.UnitId = @unitId                       AND A.CreatedDate IS NOT NULL                       AND ( PC.PaymentChangeId IS NULL                              OR PC.PaymentChangeStatusId = 3 ) --approved                UNION ALL                SELECT DISTINCT 'Unit Status'   [EventType],                                'Status'        [FilterKeyword],                                SC.SubEventType [SubEventType],                                SC.ValidFrom    [Date],                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                NULL,                                SC.UnitStatusId                FROM   @statusChanges SC) T        ORDER  BY T.Date DESC          --Print CONVERT(VARCHAR, Getdate(), 131) + '421'     SET NOCOUNT ON    END







CREATE PROC [dbo].[usp_GetActivityComments]  @associateId int,  @notedoctypeId int,  @logdat datetime,  @loggedInLMSUserId int     AS  /***************************************************************************************************  Filename:          .[Payment].[dbo].[usp_FilterPayments]    Create Date:        2020-09-08  Author:             Rajiv Vispute  Version:            1.0  Description:        ****************************************************************************************************  SUMMARY OF CHANGES  Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments  ------------------- ------------------- ------------------------------------------------------------    1.0     2020-09-08        Erkan Cevher        LME-001              change mngmt is Cretaed            ***************************************************************************************************/     BEGIN      SELECT TOP 1 A.NoteId, A.NoteText [value], C.Name [name] FROM Common.Note A     JOIN LMSLog.[dbo].[ActivityStreamLog] B ON A.CreatedBy = B.LMSUserId     LEFT JOIN Config.Reason C ON A.ReasonId = C.ReasonId     WHERE A.CreatedBy = B.LMSUserId AND A.NoteDocTypeId = @notedoctypeId AND A.IsActive = 1 AND A.AssociateId = @associateId And A.CreatedDate is not null     AND format(A.CreatedDate, 'yyyyMMddHHmmss') between format(DATEADD(SECOND, 0, @logdat), 'yyyyMMddHHmmss') AND format(DATEADD(SECOND, 20, @logdat), 'yyyyMMddHHmmss')    order by A.NoteId DESC      --SELECT B.Id, A.NoteText [value], C.Name [name] FROM Common.Note A    --JOIN LMSLog.[dbo].[ActivityStreamLog] B ON A.CreatedBy = B.LMSUserId    --JOIN Config.Reason C ON A.ReasonId = C.ReasonId    --WHERE A.NoteDocTypeId = 1 AND A.IsActive = 1 AND A.AssociateId = 1546 AND A.CreatedDate is not null    --AND format('3/27/2020 11:22:50 PM', 'yyyyMMddHHmmss') between format(DATEADD(SECOND, -6, B.TimeStamp), 'yyyyMMddHHmmss') AND format(DATEADD(SECOND, 6, B.TimeStamp), 'yyyyMMddHHmmss')     END  







/***************************************************************************************************          Filename:          [Report].[usp_PaymentsSummary]             Create Date:                  Author:                       Version:                      Description:                  ****************************************************************************************************          SUMMARY OF CHANGES          Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments          ------------------- ------------------- ------------------------------------------------------------           2022-10-29                 Ganesh Motamarri                          Removed unused joins and columns and updated indexes       ***************************************************************************************************/                  CREATE PROC [Report].[usp_PaymentsSummary]         AS        BEGIN       SET NOCOUNT ON;          DECLARE @TotalNumberofLandlords INT            DECLARE @TotalNumberofLandlordsWithEFT INT            DECLARE @PercentageofLandlordsEnrolledinEFT DECIMAL(9,2)            DECLARE @StartDate  DATETIME              DECLARE @EndDate    DATETIME              DECLARE @CertStartDate  CHAR(6)              DECLARE @CertEndDate    CHAR(6)            DECLARE @SixMonths TABLE (PaymentMode VARCHAR(20),PaymentMonthNumber INT,PaymnetMonthName  VARCHAR(20))                    /*Total Number of Landlords*/            SELECT @TotalNumberofLandlords=COUNT(DISTINCT u.UserId)             FROM Landlord.[User] u            JOIN Landlord.Assignment  a WITH(NOLOCK) ON u.UserId=a.UserId            WHERE u.IsActive=1             AND u.LandlordRequestStatusId=1            AND a.IsActive=1            AND a.UserTypeId= 2 --'Payee'                                      --PRINT @TotalNumberofLandlords                    /*Total Landlords that have an EFT Account*/            SELECT @TotalNumberofLandlordsWithEFT=COUNT(DISTINCT u.UserId)             FROM Landlord.[User] u            JOIN Landlord.Bank b WITH(NOLOCK) ON u.UserId=b.UserId            WHERE u.IsActive=1            AND u.LandlordRequestStatusId=1            AND b.IsActive=1                    --PRINT @TotalNumberofLandlordsWithEFT                    /*Percentage of Landlords Enrolled in EFT*/              IF (@TotalNumberofLandlords>0)      Begin         SELECT @PercentageofLandlordsEnrolledinEFT= CAST(((TotalCasesWithEFT*1.0/@TotalNumberofLandlords*1.0)*100) AS NUMERIC(9,2))            FROM (           SELECT COUNT(DISTINCT lu.UserId) TotalCasesWithEFT           FROM Payment.PaymentInstruction A WITH(NOLOCK)           JOIN Payment.PaymentDetail B WITH(NOLOCK) ON A.PaymentInstructionId=B.PaymentInstructionId AND B.IsActive=1            AND A.payeepaymentmodeid IS NOT NULL AND B.PaymentStatusId=1 AND A.IsActive=1           JOIN Landlord.PayeePaymentMode D WITH(NOLOCK) ON A.PayeePaymentModeId = D.PayeePaymentModeId  AND D.IsActive=1           JOIN Landlord.Assignment la WITH(NOLOCK) ON D.AssignmentId=la.AssignmentId AND la.IsActive=1 AND la.UserTypeId=2           JOIN Landlord.Bank lb WITH(NOLOCK) ON lb.UserId=la.UserId AND lb.IsApproved=1 AND lb.IsActive=1           JOIN Landlord.[User] lu WITH(NOLOCK) ON lu.UserId=lb.UserId AND lu.IsActive=1 AND lu.LandlordRequestStatusId=1                 )sr                END                       SELECT  @TotalNumberofLandlords AS [TotalNumberOfLandlords]                                            ,@TotalNumberofLandlordsWithEFT AS [TotalLandlordHaveEFTAccount]                                            ,@PercentageofLandlordsEnrolledinEFT [PercentLandlordEFTEnrolled]                                  /*EFT Enrollment % by Subsidy Program*/          SELECT  CASE              WHEN Total>0 THEN CAST((([EFT Enrollment Count]*1.0/Total*1.0)*100) AS NUMERIC(9,2))             ELSE 0            END AS [EFTEnrollmentPercent]            ,sr1.[SubsidyProgram]            ,sr1.ProgramId          FROM          (           SELECT p1.ProgramId,p1.Name AS [SubsidyProgram],COUNT(DISTINCT A.ApplicationId) [EFT Enrollment Count]           FROM Tenant.Application A   WITH(NOLOCK)         JOIN Tenant.Tenant T WITH(NOLOCK) ON A.TenantId=T.TenantId AND A.ApplicationStatusId=9  AND A.IsActive=1 AND T.IsActive=1 AND T.CaseStatusId=2 AND T.LMSCaseNumber IS NOT NULL           JOIN Landlord.Leasing l WITH(NOLOCK) ON T.TenantId=l.TenantId AND l.IsActive=1           JOIN Landlord.Assignment  la1 WITH(NOLOCK) ON l.UnitId=la1.UnitId AND la1.IsActive=1 AND la1.PropertyId IS NOT NULL AND la1.UnitId IS NOT NULL AND la1.UserTypeId=2           JOIN Landlord.Bank lb WITH(NOLOCK) ON la1.UserId=lb.UserId AND  lb.IsApproved=1 AND lb.IsActive=1           JOIN Landlord.PayeePaymentMode D WITH(NOLOCK) ON la1.AssignmentId = D.AssignmentId  AND D.IsActive=1           JOIN Payment.PaymentInstruction p WITH(NOLOCK) ON D.PayeePaymentModeId=p.PayeePaymentModeId AND p.IsActive=1 AND p.payeepaymentmodeid IS NOT NULL           JOIN Payment.PaymentDetail B WITH(NOLOCK) ON p.PaymentInstructionId=B.PaymentInstructionId AND B.IsActive=1 AND B.PaymentStatusId=1           RIGHT JOIN [Config].[Program] p1 ON A.ProgramId=p1.ProgramId           WHERE p1.IsActive=1           GROUP BY p1.ProgramId,p1.Name           ) sr1          JOIN           (            SELECT p1.ProgramId,p1.Name AS [SubsidyProgram],COUNT(DISTINCT A.ApplicationId) AS Total           FROM Tenant.Application A   WITH(NOLOCK)         JOIN Tenant.Tenant T WITH(NOLOCK) ON A.TenantId=T.TenantId AND A.ApplicationStatusId=9 AND A.IsActive=1   AND T.IsActive=1 AND T.CaseStatusId=2 AND T.LMSCaseNumber IS NOT NULL           RIGHT JOIN [Config].[Program] p1 ON A.ProgramId=p1.ProgramId           WHERE p1.IsActive=1           GROUP BY p1.ProgramId,p1.Name            ) sr2 ON sr1.ProgramId=sr2.ProgramId                                                          SELECT   @StartDate = DATEADD(mm,-5,DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0))                            ,@EndDate   = EOMONTH(GETDATE());                   SET         @CertStartDate = CONVERT(CHAR(6),@StartDate,12)                               SET         @CertEndDate = CONVERT(CHAR(6),@EndDate,12)                ;WITH ListDates (AllDates)    AS    (SELECT      @StartDate AS DATE     UNION ALL     SELECT      DATEADD(MONTH, 1, AllDates)     FROM ListDates     WHERE AllDates < DATEADD(mm, -1, @EndDate))    INSERT INTO @SixMonths (PaymentMode, PaymentMonthNumber, PaymnetMonthName)     SELECT      PaymentMode, PaymentMonthNumber, PaymnetMonthName     FROM (SELECT       'Check' AS PaymentMode      UNION      SELECT       'EFT' AS PaymentMode) S       CROSS JOIN (SELECT       FORMAT(AllDates, 'yyMM') AS PaymentMonthNumber         ,FORMAT(AllDates, 'MMM-yy') AS PaymnetMonthName      FROM ListDates) R                               IF OBJECT_ID('tempdb..#Payments') IS NOT NULL            DROP TABLE #Payments                                  /*Payment Transactions and Paid Amount by Payment Method*/                                  SELECT ISNULL(CASE WHEN B.ClaimId > 0             THEN ( SELECT TOP 1 WMSCaseNumber FROM Landlord.SecurityVoucher X WITH (NOLOCK) JOIN Landlord.Claim Y WITH (NOLOCK) ON X.SecurityVoucherId = Y.SecurityVoucherId WHERE Y.ClaimId = B.ClaimId )            ELSE ISNULL(H.WMSCaseNumber, H1.WMSCaseNumber) END,'N/A') [WMSCaseNumber],'Paid' AS PaymentStatus,n.Name AS PaymentMode,a.PaymentStartDate,a.PaymentDate,A.Amount            ,FORMAT (a.PaymentStartDate, 'MMM-yy') AS PaymnetMonthName            ,FORMAT (a.PaymentStartDate, 'yyMM') AS PaymentMonthNumber          INTO #Payments          FROM Payment.PaymentDetail A   WITH(NOLOCK)        JOIN Payment.PaymentInstruction B WITH(NOLOCK) ON A.PaymentInstructionId = B.PaymentInstructionId          JOIN Landlord.PayeePaymentMode D WITH(NOLOCK) ON B.PayeePaymentModeId = D.PayeePaymentModeId            JOIN Config.PaymentMode N WITH(NOLOCK) ON D.PaymentModeId = N.PaymentModeId           LEFT JOIN Tenant.Application C WITH(NOLOCK) ON B.ApplicationId = C.ApplicationId          LEFT JOIN Tenant.Tenant H WITH(NOLOCK) ON C.TenantId = H.TenantId           LEFT JOIN Landlord.PaymentChange D2 WITH(NOLOCK) ON B.PaymentChangeId = D2.PaymentChangeId          LEFT JOIN Tenant.Tenant H1 WITH(NOLOCK) ON D2.TenantId = H1.TenantId           WHERE a.PaymentStatusId = 7 --ps.Name='Paid'          AND n.PaymentModeId IN (2, 1) -- ('Check','EFT')          AND a.PaymentStartDate BETWEEN @StartDate AND @EndDate          UNION          SELECT ISNULL(CaseNo, 'N/A') AS WMSCaseNumber,Y.PaymentStatusDescription Name,CheckPrefix,[dbo].[CertsDateConverter](A.PeriodCoveredStartDate) [PaymentStartDate],PaidDate,PaidAmount          ,FORMAT (cast(A.PeriodCoveredStartDate AS DATE), 'MMM-yy') AS PaymnetMonthName          ,FORMAT (CASt(A.PeriodCoveredStartDate AS DATE), 'yyMM') PaymentMonthNumber          FROM Payment.CERTS  A  WITH(NOLOCK)        JOIN Config.CertsLMSStatusLookup Y WITH(NOLOCK) ON  A.StatusCode  = Y.CertsStatusCodeId      WHERE Y.PaymentStatusId =7 -- Y.Name = 'Paid'          AND CheckPrefix IN ('CHECK','EFT')          AND [dbo].[CertsDateConverter](A.PeriodCoveredStartDate) BETWEEN @StartDate AND @EndDate                                          SELECT DISTINCT sm.PaymentMode,sm.PaymnetMonthName,sm.PaymentMonthNumber,Transactions,[Transactions%],CAST(Amount AS NUMERIC(18,2)) Amount          FROM @SixMonths sm          LEFT JOIN          (           SELECT PaymentMode,PaymnetMonthName,p.PaymentMonthNumber,Transactions,            CASE              WHEN TotalTransactions>0 THEN CAST(((Transactions*1.0/TotalTransactions*1.0)*100) AS NUMERIC(9,2))             ELSE 0            END [Transactions%],Amount           FROM             (             SELECT PaymentMode,PaymnetMonthName,PaymentMonthNumber,COUNT([WMSCaseNumber]) AS Transactions, SUM(Amount) AS Amount             FROM #Payments              GROUP BY PaymentMode,PaymnetMonthName,PaymentMonthNumber            ) P            JOIN            (             SELECT PaymentMonthNumber,COUNT([WMSCaseNumber]) TotalTransactions             FROM #Payments              GROUP BY PaymentMonthNumber            ) t ON P.PaymentMonthNumber=t.PaymentMonthNumber                                                                  )sr  ON sm.PaymentMonthNumber=sr.PaymentMonthNumber AND sm.PaymentMode=sr.PaymentMode          ORDER BY sm.PaymentMode DESC,sm.PaymentMonthNumber                 --          /*Payments Certs*/          IF OBJECT_ID('tempdb..#PaymentsCerts') IS NOT NULL          DROP TABLE #PaymentsCerts                  SELECT sr.CertsId,sr.PaymentDetailId,sr.WMSCaseNumber,sr.PaymentStatus,sr.PaymentStartDate               ,CAST(FORMAT (sr.PaymentStartDate, 'MMM-yy') AS VARCHAR(20)) AS PaymnetMonthName                  ,CAST(FORMAT (sr.PaymentStartDate, 'yyMM') AS VARCHAR(20)) AS PaymentMonthNumber          INTO #PaymentsCerts          FROM          (              SELECT  A.CertsId,A.PaymentDetailId,ISNULL(CaseNo, 'N/A') AS WMSCaseNumber                ,A.[status] AS PaymentStatus                ,CAST(A.PeriodCoveredStartDate AS DATE) [PaymentStartDate]                   FROM Payment.CERTS A              WHERE A.PeriodCoveredStartDate BETWEEN @CertStartDate AND @CertEndDate       AND A.StatusCode IN (341,240,2,228,9,4)            AND A.PaymentDetailId IS NOT NULL              AND ISDATE(A.PeriodCoveredStartDate)=1                ) sr                  CREATE CLUSTERED INDEX IDX_#PaymentsCerts_CertsId ON #PaymentsCerts(CertsId)          CREATE NONCLUSTERED INDEX IDX_#PaymentsCerts_PaymentDetailId ON #PaymentsCerts(PaymentDetailId)                  IF OBJECT_ID('tempdb..#MonthPayments') IS NOT NULL              DROP TABLE #MonthPayments                  SELECT  DISTINCT A.PaymentDetailId,ISNULL(CASE WHEN B.ClaimId > 0                     THEN ( SELECT TOP 1 WMSCaseNumber FROM Landlord.SecurityVoucher X JOIN Landlord.Claim Y  ON X.SecurityVoucherId = Y.SecurityVoucherId WHERE Y.ClaimId = B.ClaimId )                    ELSE ISNULL(H.WMSCaseNumber, H1.WMSCaseNumber) END,'N/A') [WMSCaseNumber]            ,ps.Name AS PaymentStatus            ,CAST(FORMAT (a.PaymentStartDate, 'MMM-yy') AS VARCHAR(20)) AS PaymnetMonthName            ,CAST(FORMAT (a.PaymentStartDate, 'yyMM') AS VARCHAR(20)) AS PaymentMonthNumber          INTO #MonthPayments          FROM Payment.PaymentDetail A   WITH(NOLOCK)        LEFT JOIN Payment.PaymentInstruction B WITH(NOLOCK) ON A.PaymentInstructionId = B.PaymentInstructionId          LEFT JOIN Landlord.PayeePaymentMode D WITH(NOLOCK) ON B.PayeePaymentModeId = D.PayeePaymentModeId            LEFT JOIN Config.PaymentStatus ps WITH(NOLOCK) ON a.PaymentStatusId=ps.PaymentStatusId          LEFT JOIN Tenant.Application C WITH(NOLOCK) ON B.ApplicationId = C.ApplicationId          LEFT JOIN Tenant.Tenant H WITH(NOLOCK) ON C.TenantId = H.TenantId           LEFT JOIN Landlord.PaymentChange D2 WITH(NOLOCK) ON B.PaymentChangeId = D2.PaymentChangeId          LEFT JOIN Tenant.Tenant H1 WITH(NOLOCK) ON D2.TenantId = H1.TenantId           WHERE A.IsActive=1          AND a.PaymentStatusId IN (7, 8, 9, 10, 11 ,12, 5)        AND a.PaymentStartDate BETWEEN @StartDate AND @EndDate          UNION ALL          SELECT sr.PaymentDetailId,sr.WMSCaseNumber,sr.PaymentStatus,        sr.PaymnetMonthName,sr.PaymentMonthNumber          FROM #PaymentsCerts sr                                                 CREATE NONCLUSTERED INDEX IDX_MonthPayments_PaymentMonthNumber ON #MonthPayments(PaymentMonthNumber)                  SELECT DISTINCT sm.PaymnetMonthName,sm.PaymentMonthNumber,SuccessfulPayments,UnsuccessfulPayments,TotalPayments          FROM (SELECT DISTINCT PaymnetMonthName,PaymentMonthNumber FROM @SixMonths) sm          LEFT JOIN          (              SELECT  PaymnetMonthName                ,PaymentMonthNumber                ,SUM(CASE WHEN PaymentStatus='Paid' THEN 1 ELSE 0 END) AS SuccessfulPayments                ,SUM(CASE WHEN PaymentStatus IN ('Rejected','Stop','Void','Cancelled','Stale','WMS Error') THEN 1 ELSE 0 END) AS UnsuccessfulPayments                ,COUNT([WMSCaseNumber]) AS TotalPayments              FROM #MonthPayments              GROUP BY PaymnetMonthName,PaymentMonthNumber          )sr  ON sm.PaymentMonthNumber=sr.PaymentMonthNumber          ORDER BY sm. PaymentMonthNumber                  /*Manual Payments - Month*/          IF OBJECT_ID('tempdb..#ManualPayments') IS NOT NULL          DROP TABLE #ManualPayments                  SELECT ISNULL(CASE WHEN B.ClaimId > 0            THEN ( SELECT TOP 1 WMSCaseNumber FROM Landlord.SecurityVoucher X JOIN Landlord.Claim Y  ON X.SecurityVoucherId = Y.SecurityVoucherId WHERE Y.ClaimId = B.ClaimId )           ELSE ISNULL(H.WMSCaseNumber, H1.WMSCaseNumber) END,'N/A') [WMSCaseNumber]         ,pct.Name AS PaymentType           ,CAST(FORMAT (a.PaymentStartDate, 'MMM-yy') AS VARCHAR(20)) AS PaymnetMonthName           ,CAST(FORMAT (a.PaymentStartDate, 'yyMM') AS  VARCHAR(20)) PaymentMonthNumber          INTO #ManualPayments          FROM Payment.PaymentDetail A   WITH(NOLOCK)        JOIN Payment.PaymentInstruction B WITH(NOLOCK) ON A.PaymentInstructionId = B.PaymentInstructionId          JOIN Landlord.PayeePaymentMode D WITH(NOLOCK) ON B.PayeePaymentModeId = D.PayeePaymentModeId            LEFT JOIN Tenant.Application C WITH(NOLOCK) ON B.ApplicationId = C.ApplicationId          LEFT JOIN Tenant.Tenant H WITH(NOLOCK) ON C.TenantId = H.TenantId           LEFT JOIN Landlord.PaymentChange D2 WITH(NOLOCK) ON B.PaymentChangeId = D2.PaymentChangeId          LEFT JOIN Config.PaymentChangeType pct  ON D2.PaymentChangeTypeId = pct.PaymentChangeTypeId          LEFT JOIN Tenant.Tenant H1 WITH(NOLOCK) ON D2.TenantId = H1.TenantId           WHERE A.PaymentStatusId IN (7, 8, 9, 10, 11 ,12, 5)         AND a.PaymentStartDate BETWEEN @StartDate AND @EndDate          UNION ALL          SELECT A.WMSCaseNumber,       '' AS PaymentType, A.PaymnetMonthName,A.PaymentMonthNumber          FROM #PaymentsCerts A          JOIN Landlord.PaymentChange D2 ON A.CertsId = D2.CertsId AND D2.IsActive=1 AND D2.PaymentChangeTypeId=3 -- Manual Payment                                      CREATE NONCLUSTERED INDEX IDX_#ManualPayments_PaymentMonthNumber ON #ManualPayments(PaymentMonthNumber)                 SELECT DISTINCT sm.PaymnetMonthName,sm.PaymentMonthNumber,[%ofmanualpayments],ManualPayments,[Totalnumberoftransactions]          FROM (SELECT DISTINCT PaymnetMonthName,PaymentMonthNumber FROM @SixMonths) sm          LEFT JOIN          (                                                   SELECT PaymnetMonthName,PaymentMonthNumber            ,CASE              WHEN TotalPayments>0 THEN CAST(((ManualPayments*1.0/TotalPayments*1.0)*100) AS NUMERIC(9,2))             ELSE 0            END [%ofmanualpayments]            ,ManualPayments            ,TotalPayments AS [Totalnumberoftransactions]           FROM             (            SELECT  PaymnetMonthName              ,PaymentMonthNumber              ,SUM(CASE WHEN PaymentType='Manual Payment' THEN 1 ELSE 0 END) AS ManualPayments              ,COUNT([WMSCaseNumber]) AS TotalPayments            FROM #ManualPayments            GROUP BY PaymnetMonthName,PaymentMonthNumber            ) src          )sr  ON sm.PaymentMonthNumber=sr.PaymentMonthNumber          ORDER BY sm. PaymentMonthNumber                END


/***************************************************************************************************      Filename:          [Report].[usp_ApplicationSummary]         Create Date:              Author:                   Version:                  Description:              ****************************************************************************************************      SUMMARY OF CHANGES      Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments      ------------------- ------------------- ------------------------------------------------------------       2.0     2022-10-29          Vishnu Raj                          Removed unused joins & columns, added nocount & NOLOCK    ***************************************************************************************************/      CREATE PROC [Report].[usp_ApplicationSummary]   AS  BEGIN  set nocount on;     set nocount on;             DECLARE @TotalPendingApplications INT       DECLARE @StartDate  DATETIME         DECLARE @EndDate    DATETIME         DECLARE @SixMonths TABLE (ApplicationMonthNumber INT,ApplicationMonthName  VARCHAR(20))                   SELECT @TotalPendingApplications=COUNT(DISTINCT A.ApplicationId)       FROM Tenant.Application A WITH(NOLOCK)       JOIN Tenant.Tenant B WITH(NOLOCK) ON A.TenantId = B.TenantId AND B.IsActive=1       JOIN Tenant.HouseholdMemberProfile C WITH(NOLOCK) on B.HouseholdMemberProfileId = C.HouseholdMemberProfileId AND  C.IsActive=1       WHERE A.IsActive=1       AND A.ApplicationStatusId IN (7,12,13,6,8,5,4,2,3)       AND ISNULL(A.IsPreApprovedRenewalApplication,0)<>1             /*       Total Pending Applications       Applications - Unassigned       Applications - Assigned       Applications - Actions Overdue       */       SELECT @TotalPendingApplications AS TotalPendingApplications         ,SUM(CASE WHEN B.AssignedTo IS NULL THEN 1 ELSE 0 END) AS ApplicationsUnassigned         ,SUM(CASE WHEN B.AssignedTo IS NOT NULL THEN 1 ELSE 0 END) AS ApplicationsAssigned         ,SUM(CASE WHEN E.Name='Completed' AND B.CompletedDate>B.DueDate THEN 1 ELSE 0 END) AS ApplicationsActionsOverdue       FROM Tenant.Application A WITH(NOLOCK)       JOIN Task.Task B WITH(NOLOCK) ON A.ApplicationId=B.AssociateId       JOIN [Config].[TaskType] C WITH(NOLOCK) ON B.TaskTypeId=C.TaskTypeId       LEFT JOIN Config.TaskStatus E WITH(NOLOCK) ON B.TaskStatusId=E.TaskStatusId       WHERE A.IsActive=1 AND       C.TaskCategoryId = 1       AND C.Name IN ('Pending Submission','Pending Assessment','Pending QA','Pending Review','Pending Decision','Pending Follow-up')             /*Applications - Pending*/       SELECT P.ProgramId,P.Name AS SubsidyProgram,COUNT(DISTINCT A.ApplicationId) AS ApplicationsPending       FROM Tenant.Application A WITH(NOLOCK)       JOIN Tenant.Tenant B WITH(NOLOCK) ON A.TenantId = B.TenantId AND B.IsActive=1       JOIN Tenant.HouseholdMemberProfile C WITH(NOLOCK) on B.HouseholdMemberProfileId = C.HouseholdMemberProfileId AND  C.IsActive=1       AND A.IsActive = 1       AND A.ApplicationStatusId IN (7,12,13,6,8,5,4,2,3)       RIGHT JOIN [Config].[Program] P WITH(NOLOCK) ON A.ProgramId=P.ProgramId              WHERE P.IsActive=1       AND ISNULL(A.IsPreApprovedRenewalApplication,0)<>1       GROUP BY P.ProgramId,P.Name                   /*Active Subsidies by Program*/       SELECT D.ProgramId,D.Name AS SubsidyProgram,COUNT(DISTINCT B.TenantId) AS ActiveTenants        FROM Tenant.Application A WITH(NOLOCK)       JOIN Tenant.Tenant B WITH(NOLOCK) ON A.TenantId=B.TenantId AND A.IsActive=1 AND B.IsActive=1 AND B.CaseStatusId=2 and A.ApplicationStatusId = 9       RIGHT JOIN [Config].[Program] D WITH(NOLOCK) ON A.ProgramId=D.ProgramId              WHERE D.IsActive=1       GROUP BY D.ProgramId,D.Name                    /*Application Volumes by Month*/       SELECT   @StartDate = DATEADD(mm,-5,DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0))                    ,@EndDate   = EOMONTH(GETDATE());                     ; WITH ListDates(AllDates)   AS (    SELECT @StartDate AS DATE             UNION ALL             SELECT DATEADD(MONTH,1,AllDates)             FROM ListDates              WHERE AllDates < @EndDate)      INSERT INTO @SixMonths (ApplicationMonthNumber,ApplicationMonthName)  SELECT FORMAT ( AllDates, 'yyMM')   AS ApplicationMonthNumber          ,FORMAT (alldates, 'MMM-yy') AS  ApplicationMonthName    FROM ListDates          --INSERT INTO @SixMonths (ApplicationMonthNumber,ApplicationMonthName)       --SELECT  FORMAT (DATEADD(MONTH, x.number, @StartDate), 'yyMM')  AS ApplicationMonthNumber       --  ,FORMAT (DATEADD(MONTH, x.number, @StartDate), 'MMM-yy') AS ApplicationMonthName       --FROM    master.dbo.spt_values x         --WHERE   x.type = 'P'                 --AND     x.number <= DATEDIFF(MONTH, @StartDate, @EndDate)                     SELECT S.ApplicationMonthName,s.ApplicationMonthNumber,Approved,Pending,Denied,Withdrawn,Total       FROM @SixMonths s       LEFT JOIN        (           SELECT FORMAT (a.CreatedDate, 'MMM-yy') AS ApplicationMonthName          ,FORMAT (a.CreatedDate, 'yyMM') AS ApplicationMonthNumber          ,SUM(CASE WHEN A.ApplicationStatusId=9 THEN 1 ELSE 0 END) AS 'Approved'          ,SUM(CASE WHEN A.ApplicationStatusId=10 THEN 1 ELSE 0 END) AS 'Denied'          ,SUM(CASE WHEN A.ApplicationStatusId=11 THEN 1 ELSE 0 END) AS 'Withdrawn'          ,SUM(CASE WHEN LTRIM(RTRIM(A.ApplicationStatusId)) IN (7,12,13,6,8,5,4,2,3) THEN 1 ELSE 0 END) AS 'Pending'          ,COUNT(DISTINCT A.ApplicationId) AS Total        FROM Tenant.Application A WITH(NOLOCK)          WHERE A.ApplicationStatusId IN (7,12,13,6,8,4,5,9,10,11)        AND CAST(a.CreatedDate AS DATE)  >= @StartDate AND CAST(a.CreatedDate AS DATE)<= @EndDate        GROUP BY FORMAT (a.CreatedDate, 'MMM-yy')           ,FORMAT (a.CreatedDate, 'yyMM')                  )sr ON s.ApplicationMonthNumber=sr.ApplicationMonthNumber                   /*Application Timeliness*/       SELECT DISTINCT sr.ProgramId         ,ApplicationTimeLinesMonthName         ,COALESCE(sa.Name,sr.ApplicationCategory) AS ApplicationCategory         ,CASE           WHEN Total>0 THEN CAST(((TimeLineCount*1.0/Total*1.0)*100) AS NUMERIC(9,2))          ELSE 0         END TimelinessPercentage       FROM        Config.ApplicationCategory sa       LEFT JOIN       (        SELECT C.ProgramId          ,CASE            WHEN po.Name = 'Community' THEN c.Name + ' Community'           WHEN po.Name = 'Shelter' AND pa.Name IS NOT NULL THEN c.Name + ' '+ pa.Name+' Shelter'           ELSE c.Name          END AS ApplicationCategory          ,FORMAT (a.CreatedDate, 'MMM-yy') AS ApplicationTimeLinesMonthName          ,COUNT(DISTINCT A.ApplicationId) TimeLineCount        FROM Tenant.Application A WITH(NOLOCK)         JOIN Config.ApplicationStatus B  WITH(NOLOCK)           ON A.ApplicationStatusId=B.ApplicationStatusId                 AND  B.Alias IN ('Complete','Withdrawn')           AND a.CreatedDate BETWEEN CONVERT(DATE,DATEADD(d,-(DAY(DATEADD(m,-1,GETDATE()-2))),DATEADD(m,-1,GETDATE()-1)),23) AND CONVERT(DATE,DATEADD(d,-(DAY(GETDATE())),GETDATE()),23)         LEFT JOIN Config.ProgramOrigin po WITH(NOLOCK) ON A.OriginId=po.ProgramOriginId         LEFT JOIN Config.ProgramAction pa WITH(NOLOCK) ON A.ActionId=pa.ProgramActionId         RIGHT JOIN [Config].[Program] C WITH(NOLOCK) ON A.ProgramId=C.ProgramId         WHERE C.IsActive=1        GROUP BY C.ProgramId,C.Name,FORMAT (a.CreatedDate, 'MMM-yy')          ,CASE            WHEN po.Name = 'Community' THEN c.Name + ' Community'           WHEN po.Name = 'Shelter' AND pa.Name IS NOT NULL THEN c.Name + ' '+ pa.Name+' Shelter'      ELSE c.Name          END       ) sr       ON sa.Name =sr.ApplicationCategory       LEFT JOIN       (        SELECT C.ProgramId          ,CASE            WHEN po.Name = 'Community' THEN c.Name + ' Community'           WHEN po.Name = 'Shelter' AND pa.Name IS NOT NULL THEN c.Name + ' '+ pa.Name+' Shelter'           ELSE c.Name          END AS ApplicationCategory          ,COUNT(DISTINCT A.ApplicationId) AS Total        FROM Tenant.Application A WITH(NOLOCK)         JOIN Config.ApplicationStatus B  WITH(NOLOCK)           ON A.ApplicationStatusId=B.ApplicationStatusId                AND  B.Alias IN ('Complete','Withdrawn')               LEFT JOIN Config.ProgramOrigin po WITH(NOLOCK) ON A.OriginId=po.ProgramOriginId         LEFT JOIN Config.ProgramAction pa WITH(NOLOCK) ON A.ActionId=pa.ProgramActionId         RIGHT JOIN [Config].[Program] C WITH(NOLOCK) ON A.ProgramId=C.ProgramId        WHERE C.IsActive=1        GROUP BY C.ProgramId,C.Name          ,CASE            WHEN po.Name = 'Community' THEN c.Name + ' Community'           WHEN po.Name = 'Shelter' AND pa.Name IS NOT NULL THEN c.Name + ' '+ pa.Name+' Shelter'           ELSE c.Name          END       ) sr1       ON sa.Name=sr1.ApplicationCategory       END



CREATE  PROCEDURE [Task].[CreateTask]           @taskTypeId int,           @associateId int,           @lmsUserId int ,         @submissionStatus varchar(20) = null,       @multiFollowup bit = 0      AS                   BEGIN            -- =============================================    -- Author:  Fred Erlikh    -- Create date: 01/04/2021    -- Description:     -- =============================================    /****************************************************************************************************          SUMMARY OF CHANGES          Version  Date(yyyy-mm-dd)    Author             JIRA TICKET NO        Comments          ------------------- ------------------- ------------------------------------------------------------            1  2022-11-21   Ganesh Motamarri LME-18433   we are not using signalR, Task.GetTaskById is not required  ***************************************************************************************************/       DECLARE @taskCategoryId int = (SELECT TOP(1) TaskCategoryId FROM Config.TaskType WHERE TaskTypeId = @taskTypeId)                    DECLARE @taskStatusId int = 1          DECLARE @businessUnitId int          DECLARE @organizationId int          DECLARE @assignedTo int          DECLARE @assignedBy int = NULL          DECLARE @assignedDate datetime          DECLARE @createdBy int = @lmsUserId          DECLARE @adminId int = (SELECT TOP(1) AdminId FROM Admin.AdminProfile WHERE LMSUserId = @lmsUserId);                    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED                     IF (@submissionStatus = 'Returned')   --LME-10369         BEGIN          SELECT @businessUnitId = BusinessUnitId, @organizationId = OrganizationId, @assignedTo = AdminId FROM Admin.AdminProfile WHERE LMSUserId = @lmsUserId         END     ELSE IF(@submissionStatus = 'Resubmitted')  --LME-15653     BEGIN       SELECT @businessUnitId = BusinessUnitId, @organizationId = OrganizationId FROM Admin.AdminProfile WHERE LMSUserId = @lmsUserId       END      ELSE IF(@multiFollowup = 1)  --LME-17119       BEGIN       SELECT @businessUnitId = BusinessUnitId, @organizationId = OrganizationId, @assignedTo = AdminId FROM Admin.AdminProfile WHERE LMSUserId = @lmsUserId       END      ELSE         BEGIN          SELECT @businessUnitId = BusinessUnitId, @organizationId = OrganizationId, @assignedTo = AdminId FROM Task.GetTaskRouting(@taskTypeId, @associateId, @adminId)           END                  IF(Task.PendingTaskExists(@taskTypeId, @associateId) = 0)          BEGIN           INSERT INTO Task.Task (TaskTypeId, AssociateId, TaskStatusId, BusinessUnitId, OrganizationId, AssignedBy, AssignedTo, CreatedBy, CreatedDate, AssignedDate, DueDate, SubmissionStatus)           SELECT             @taskTypeId,            @associateId,            @taskStatusId,            @businessUnitId,            @organizationId,            @assignedBy,           @assignedTo ,           @createdBy,            GETDATE(),            CASE WHEN @assignedTo IS NULL THEN NULL ELSE GETDATE() END,             Task.GetDueDate(@taskTypeId, @associateId) ,          @submissionStatus                   --SELECT * FROM Task.GetTaskById(DEFAULT, @taskTypeId, @associateId)    --currently we are not using signalR      END                    SET TRANSACTION ISOLATION LEVEL READ COMMITTED                    END




  CREATE FUNCTION [Task].[PendingTaskExists]    (        @taskTypeId int,   @associateId int  )   RETURNS bit    AS    BEGIN    RETURN IIF(EXISTS (SELECT * FROM Task.Task WHERE TaskTypeId = @taskTypeId AND AssociateId = @associateId AND TaskStatusId = 1), 1, 0)    END    